def mois(a, b): return list(range(a, b + 1)) if a <= b else list(range(a, 13)) + list(range(1, b + 1))
def ag(forme, ch, hy, pi, **k): return dict(type='agaric', forme=forme, chapeau=ch, hymenium=hy, pied=pi, feuilles=True, **k)
def bo(ch, hy, pi, **k): return dict(type='bolet', forme='bombe', chapeau=ch, hymenium=hy, pied=pi, feuilles=True, **k)
def cons(ch, ch2, forme=None):
    d = dict(type='console', chapeau=ch, chapeau2=ch2)
    if forme: d['forme'] = forme
    return d
def gel(ch, forme=None, **k):
    d = dict(type='gelee', chapeau=ch, **k)
    if forme: d['forme'] = forme
    return d
