def construire():
    out = []
    for (id_, nom, latin, statut, crit, habitat, saison, m, sporee, schema, tox, prec, autres) in L:
        out.append({"id": id_, "nom": nom, "latin": latin, "autres_noms": autres, "statut": statut, "rang": "secondaire",
                    "precaution": prec, "toxicite": tox, "criteres": crit, "habitat": habitat, "saison": saison, "sporee": sporee,
                    "schema": schema, "mois": m, "confusions": [], "sources": [G1, G2] + ([ANSES] if statut in ('toxique', 'mortel') else [])})
    return out

