def appliquer_sosies(E):
    d = {e['id']: e for e in E}
    for a, b, ta, tb in SOSIES:
        for x, y, t in ((a, b, ta), (b, a, tb)):
            if y not in d[x]['confusions']: d[x]['confusions'].append(y)
            d[x].setdefault('distinguer', {})[y] = t

if __name__ == '__main__':
    P = os.path.join(ROOT, 'data', 'especes.json')
    E = json.load(open(P, encoding='utf-8')); ids = {e['id'] for e in E}
    n = 0
    for e in construire():
        if e['id'] not in ids: E.append(e); n += 1
    if n: appliquer_sosies(E)
    json.dump(E, open(P, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print(n, 'espèces ajoutées ;', len(E), 'au total')
